package com.jobmatcher.controller;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;import java.nio.charset.StandardCharsets;
@RestController @RequestMapping("/api/resume") public class ResumeController {private static final List<String> SKILLS=List.of("javascript","typescript","react","next.js","node.js","html","css","tailwind","python","sql","pandas","machine learning","statistics","data visualization","figma","user research","prototyping","copywriting","seo","aws","docker","ci/cd","linux","git","communication","project management","java","spring boot","mysql","rest api","kotlin","android","selenium","testing","manual testing","jira","mongodb","kubernetes","jenkins","wireframing");@PostMapping("/upload") public ResponseEntity<?> upload(@RequestParam("file") MultipartFile file){try{if(file.isEmpty()||file.getSize()>5*1024*1024)return ResponseEntity.badRequest().body(Map.of("error","Upload a non-empty file smaller than 5 MB."));String name=Objects.toString(file.getOriginalFilename(),"resume");String text;if(name.toLowerCase().endsWith(".pdf")){try(var doc=Loader.loadPDF(file.getBytes())){text=new PDFTextStripper().getText(doc);}}else if(name.toLowerCase().endsWith(".txt")){text=new String(file.getBytes(),StandardCharsets.UTF_8);}else return ResponseEntity.badRequest().body(Map.of("error","Supported formats: PDF and TXT."));String lower=text.toLowerCase(Locale.ROOT);List<String> found=SKILLS.stream().filter(s->java.util.regex.Pattern.compile("(?i)(?<![a-z0-9])"+java.util.regex.Pattern.quote(s)+"(?![a-z0-9])").matcher(lower).find()).toList();return ResponseEntity.ok(Map.of("message","Resume analyzed successfully!","fileName",name,"extractedText",text,"skills",found));}catch(Exception e){return ResponseEntity.status(400).body(Map.of("error","Unable to read this resume file."));}}}
